INSERT INTO biblioteca_jogos.avaliacoes (id_usuario, id_jogo, nota, comentario, data_avaliacao)
SELECT p.id_usuario, pr.id_jogo, pr.nota, pr.comentario,
       now() - (pr.dias_atras || ' days')::interval
FROM pares pr
JOIN pool_usuarios p ON p.rn = pr.rn
ON CONFLICT (id_usuario, id_jogo) DO NOTHING;

